using System;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using GameCombat;
using GameCombat.AgentContract;

[InitializeOnLoad]
public static class Phase5AgentValidation {
 static int checks; static bool started;
 static Phase5AgentValidation(){if(SessionState.GetBool("Phase5AgentValidation",false))EditorApplication.update+=Tick;}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/GameScene.unity");SessionState.SetBool("Phase5AgentValidation",true);EditorApplication.update+=Tick;EditorApplication.EnterPlaymode();}
 static void Check(bool value,string message){if(!value)throw new Exception(message);checks++;Debug.Log("PHASE5_CHECK "+message);}
 static void Tick(){if(!EditorApplication.isPlaying || started)return;started=true;SessionState.SetBool("Phase5AgentValidation",false);try{Rules();Debug.Log("PHASE5_AGENT_VALIDATION_PASS checks="+checks);Finish(0);}catch(Exception e){Debug.LogException(e);Finish(1);}}
 static object Invoke(object target,string name,params object[] args)=>target.GetType().GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(target,args);
 static void Rules(){
  var stream=new EnemyObservationStream();var cue=new CombatObservation{visible=true,time=0,relativePosition=Vector3.one,opponentVelocity=Vector3.one,opponentForward=Vector3.forward,opponentHealth=.9f,opponentPosture=.2f,opponentAttackId=7,opponentAction=CombatAction.Attack,opponentPhase=AttackPhase.Windup,opponentWindup=.5f,opponentElapsed=.1f,opponentReach=2,opponentProgress=.2f};
  Check(!stream.Sample(cue).visible,"initial cues withheld");cue.time=.14;Check(!stream.Sample(cue).visible,"no early cue at 140ms");cue.time=.16;var delayed=stream.Sample(cue);Check(delayed.visible && delayed.opponentAttackId==7,"cue appears at 160ms");cue.visible=false;var hidden=stream.Sample(cue);Check(!hidden.visible && hidden.relativePosition==Vector3.zero && hidden.opponentVelocity==Vector3.zero && hidden.opponentAttackId==0 && hidden.opponentElapsed==0 && hidden.opponentWindup==0 && hidden.opponentHealth==0,"visibility loss immediately clears every public opponent field");cue.visible=true;cue.time=.18;Check(!stream.Sample(cue).visible,"reacquisition cannot reuse history");
  var body=UnityEngine.Object.FindAnyObjectByType<enemy>();var actor=body.GetComponent<Combatant>();var host=body.GetComponent<EnemyBrainHost>();
  UnityEngine.Object.FindAnyObjectByType<CombatWorld>().enabled=false;host.enabled=false;
  host.agentPolicy=null; // Explicit missing-adapter fixture; GameScene may now have the optional candidate installed.
  Check(host.SetMode(EnemyControlMode.ML)==BrainSwitchResult.Unavailable && host.ActiveMode==EnemyControlMode.Normal,"missing model/adapter retains Normal");
  var policy=body.gameObject.AddComponent<ContractHeuristicPolicy>();host.agentPolicy=policy;Check(host.SetMode(EnemyControlMode.ML)==BrainSwitchResult.Applied,"explicit heuristic acquires host");
  var observation=new CombatObservation{visible=true,grounded=true,relativePosition=Vector3.forward*2,opponentHealth=1,opponentForward=Vector3.back};
  var frame=(DecisionFrame)Invoke(host,"BuildAgentFrame",observation,true);
  Check(frame.observations.Length==66 && DecisionFrame.ObservationNames.Length==66,"observation size and ordered schema 66");for(int i=0;i<66;i++)Check(float.IsFinite(frame.observations[i]) && Mathf.Abs(frame.observations[i])<=1,"finite normalized slot "+i);
  Check(frame.observations[0]==1 && frame.observations[2]==1 && frame.observations[5]==1 && frame.observations[11]==1 && frame.observations[20]==1,"versioned self/action/opponent ordering");
  float capture=Time.captureDeltaTime;Time.captureDeltaTime=.02f;Check(TrainingMotionEvaluation.TryPrepare(actor,true,out var lease,out _),"validated motion evaluation can be prepared");lease.Dispose();Time.captureDeltaTime=0;Check(!TrainingMotionEvaluation.TryPrepare(actor,true,out _,out _),"unmeasured animation cadence blocks training preparation");Time.captureDeltaTime=capture;
  policy.combat=2;Invoke(host,"CollectAgent",observation,true,true);var first=policy.LastFrame;Check(actor.Runner.Action==CombatAction.Free,"callback buffers without executing");actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(actor.Runner.Action==CombatAction.Attack,"buffer executes on subsequent combat tick");ulong attack=actor.Runner.AttackId;policy.LastCallback(first.generation,first.sequence,0,3);Invoke(host,"CollectAgent",observation,true,true);Check(actor.Runner.AttackId==attack,"duplicate callback cannot repeat request");
  var committed=(DecisionFrame)Invoke(host,"BuildAgentFrame",observation,true);Check(committed.movementAllowed[0] && committed.combatAllowed[0] && !committed.combatAllowed[2] && !committed.combatAllowed[3] && !committed.combatAllowed[4],"commitment masks and neutral availability");
  Check(host.SetMode(EnemyControlMode.Normal)==BrainSwitchResult.Deferred,"switch cannot cancel commitment");while(actor.Runner.Action!=CombatAction.Free)actor.Runner.Tick(.02f);host.SetMode(EnemyControlMode.Normal);policy.LastCallback(first.generation,first.sequence,0,3);Check(host.Intent.request==CombatRequest.None,"stale owner callback rejected");
  foreach(int action in new[]{1,2,3,4,0}){host.SetMode(EnemyControlMode.ML);policy.combat=action;Invoke(host,"CollectAgent",observation,true,true);actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(action==1?actor.Runner.Guarding:action==2 || action==3?actor.Runner.Action==CombatAction.Attack:action==4?actor.Runner.Action==CombatAction.Dodge:!actor.Runner.Guarding,"contract action through shared runner "+action);while(actor.Runner.Action!=CombatAction.Free)actor.Runner.Tick(.02f);actor.Runner.SetGuard(false);actor.Runner.Tick(1);host.SetMode(EnemyControlMode.Normal);}
  host.SetMode(EnemyControlMode.ML);policy.combat=2;Invoke(host,"CollectAgent",observation,true,true);actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,false,true);Check(actor.Runner.Action==CombatAction.Free && host.Intent.request==CombatRequest.None,"live visibility loss suppresses buffered attack");
  host.SetMode(EnemyControlMode.Normal);host.SetMode(EnemyControlMode.ML);policy.combat=0;Invoke(host,"CollectAgent",observation,true,true);uint cadence=policy.LastFrame.sequence;actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(policy.LastFrame.sequence==cadence,"no new decision between three-tick boundaries");actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(policy.LastFrame.sequence!=cadence,"new decision exactly every three ticks");
  host.SetMode(EnemyControlMode.Normal);host.SetMode(EnemyControlMode.ML);policy.holdCallback=true;Invoke(host,"CollectAgent",observation,true,true);var stale=policy.LastFrame;var callback=policy.LastCallback;actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(host.ActiveMode==EnemyControlMode.Normal,"missed designated callback safely falls back");callback(stale.generation,stale.sequence,0,2);Check(actor.Runner.Action==CombatAction.Free,"callback after deadline cannot submit");policy.holdCallback=false;
  var airborne=(DecisionFrame)Invoke(host,"BuildAgentFrame",observation,false);Check(!airborne.combatAllowed[1] && !airborne.combatAllowed[2] && !airborne.combatAllowed[3] && !airborne.combatAllowed[4],"airborne legality masks");
  host.SetMode(EnemyControlMode.ML);policy.holdCallback=true;Invoke(host,"CollectAgent",observation,true,true);stale=policy.LastFrame;callback=policy.LastCallback;uint generation=host.Generation;host.enabled=true;host.enabled=false;callback(stale.generation,stale.sequence,0,2);Check(host.Generation!=generation && actor.Runner.Action==CombatAction.Free && host.Intent.request==CombatRequest.None,"disable invalidates pending callback and releases ownership");policy.holdCallback=false;host.SetMode(EnemyControlMode.Normal);
  for(int move=0;move<9;move++)Check(EnemyBrainHost.AgentMovement(move).magnitude<1.0001f,"normalized movement choice "+move);
  host.SetMode(EnemyControlMode.Normal);host.GetType().GetProperty("InCombat").SetValue(host,true);host.SetMode(EnemyControlMode.ML);policy.combat=0;
  for(int move=0;move<9;move++){policy.movement=move;host.SetMode(EnemyControlMode.Normal);host.SetMode(EnemyControlMode.ML);Invoke(host,"CollectAgent",observation,true,true);actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);actor.Runner.Move();Check(body.horizontalVelocity.magnitude<=2.501f,"movement branch uses shared motor "+move);}
  policy.movement=0;host.SetMode(EnemyControlMode.Normal);
  host.SetMode(EnemyControlMode.Normal);var child=new GameObject("ML contract fixture");child.SetActive(false);child.transform.SetParent(body.transform,false);
  var parameters=child.AddComponent<Unity.MLAgents.Policies.BehaviorParameters>();parameters.BrainParameters.VectorObservationSize=66;parameters.BrainParameters.NumStackedVectorObservations=3;parameters.BrainParameters.ActionSpec=Unity.MLAgents.Actuators.ActionSpec.MakeDiscrete(9,5);parameters.BehaviorType=Unity.MLAgents.Policies.BehaviorType.HeuristicOnly;
  var learning=child.AddComponent<GameCombat.ML.EnemyLearningAgent>();learning.testHeuristic=true;child.SetActive(true);host.agentPolicy=learning;
  bool auto=Unity.MLAgents.Academy.Instance.AutomaticSteppingEnabled;Unity.MLAgents.Academy.Instance.AutomaticSteppingEnabled=false;
  try{for(int decision=0;decision<10;decision++){Check(host.SetMode(EnemyControlMode.ML)==BrainSwitchResult.Applied,"actual Agent heuristic activation "+decision);Invoke(host,"CollectAgent",observation,true,true);Unity.MLAgents.Academy.Instance.EnvironmentStep();actor.Runner.Tick(.02f);Invoke(host,"CollectAgent",observation,true,true);Check(host.ActiveMode==EnemyControlMode.ML,"actual Agent callback meets designated tick "+decision);while(actor.Runner.Action!=CombatAction.Free)actor.Runner.Tick(.02f);actor.Runner.SetGuard(false);actor.Runner.Tick(1);host.SetMode(EnemyControlMode.Normal);}
   Check(!Unity.MLAgents.Academy.Instance.IsCommunicatorOn && !Unity.MLAgents.CommunicatorFactory.Enabled,"actual Agent never connects to Python");learning.testHeuristic=false;Check(host.SetMode(EnemyControlMode.ML)==BrainSwitchResult.Unavailable,"actual Agent missing model falls back");
  }finally{Unity.MLAgents.Academy.Instance.AutomaticSteppingEnabled=auto;UnityEngine.Object.DestroyImmediate(child);}
 }
 static void Finish(int code){if(Application.isBatchMode)EditorApplication.Exit(code);else EditorApplication.isPlaying=false;}
}
